(window.ArduinoSketches=window.ArduinoSketches||{})["b1_04_buggy_silent"]={"ok":true,"flash":998,"ram":9,"program":"","name":"b1_04_buggy_silent","source":"// ==================================================================\n//   BAND 1, PART 7b  -  A FAULT WITH NO ERROR MESSAGE\n//\n//   WHAT IT DOES\n//     Lights the red LED, then the yellow LED, then nothing.\n//     The green LED never comes on.\n//\n//     It compiles with no error. It uploads with no error.\n//     The wiring is correct.\n//\n//   WHAT TO DO\n//     Find the fault BY READING. Do not touch the breadboard.\n//     Compare the names at the top with what the third block uses.\n//\n//     Band 1 Part 7b has the answer if you are stuck.\n//\n//   WIRING\n//     Same as b1_02.\n// ==================================================================\n\nint redPin = 9;\nint yellowPin = 8;\nint greenPin = 7;\n\nvoid setup() {\n  pinMode(redPin, OUTPUT);\n  pinMode(yellowPin, OUTPUT);\n  pinMode(greenPin, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(redPin, HIGH);\n  delay(1000);\n  digitalWrite(redPin, LOW);\n\n  digitalWrite(yellowPin, HIGH);\n  delay(1000);\n  digitalWrite(yellowPin, LOW);\n\n  digitalWrite(6, HIGH);\n  delay(1000);\n  digitalWrite(6, LOW);\n}\n","compiler":"arduino-cli 1.5.1, arduino:avr:uno"};
